-- =============================================================================
-- init_stocks_db.sql
-- Minimal stocks database for benchmarking.
-- Only the tables and data required to run:
--   SELECT l.code, e.ts, e.open, e.high, e.low, e.close, e.volume
--   FROM listing l INNER JOIN adj_eod e ON l.listing_id = e.listing_id
--   WHERE l.code = $1 AND l.exchange_code = $2 AND e.volume > 0
--   ORDER BY e.ts DESC LIMIT $3
--
-- Run as:
--   psql -U postgres -h <host> -d postgres -f scripts/init_stocks_db.sql
-- =============================================================================

\echo '>>> Dropping and recreating stocks database...'
DROP DATABASE IF EXISTS stocks;
CREATE DATABASE stocks;

-- Create tulip user at cluster level if it does not already exist
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'tulip') THEN
    CREATE USER tulip WITH PASSWORD 'tulip';
  END IF;
END
$$;

\c stocks

-- Grant privileges to tulip on stocks
GRANT CONNECT ON DATABASE stocks TO tulip;
GRANT USAGE ON SCHEMA public TO tulip;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO tulip;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO tulip;

-- ---------------------------------------------------------------------------
-- Schema
-- ---------------------------------------------------------------------------

CREATE TABLE exchange (
    exchange_code VARCHAR NOT NULL,
    name          VARCHAR NOT NULL,
    timezone      VARCHAR NOT NULL,
    CONSTRAINT exchange_pkey PRIMARY KEY (exchange_code)
);

CREATE TABLE listing (
    listing_id    BIGINT  NOT NULL,
    code          VARCHAR NOT NULL,
    exchange_code VARCHAR NOT NULL,
    CONSTRAINT listing_pkey PRIMARY KEY (listing_id),
    CONSTRAINT listing_exchange_code_fkey FOREIGN KEY (exchange_code)
        REFERENCES exchange (exchange_code)
);

CREATE INDEX idx_listing_code_exchange ON listing (code, exchange_code);

CREATE TABLE adj_eod (
    listing_id BIGINT  NOT NULL,
    ts         DATE    NOT NULL,
    open       NUMERIC NOT NULL,
    high       NUMERIC NOT NULL,
    low        NUMERIC NOT NULL,
    close      NUMERIC NOT NULL,
    volume     NUMERIC NOT NULL,
    CONSTRAINT adj_eod_pkey PRIMARY KEY (listing_id, ts),
    CONSTRAINT adj_eod_listing_id_fkey FOREIGN KEY (listing_id)
        REFERENCES listing (listing_id)
);

CREATE INDEX idx_adj_eod_listing_ts ON adj_eod (listing_id, ts DESC);
CREATE INDEX idx_adj_eod_volume_partial ON adj_eod (listing_id, ts DESC)
    WHERE volume > 0;

-- ---------------------------------------------------------------------------
-- Seed: exchanges
-- ---------------------------------------------------------------------------


-- ---------------------------------------------------------------------------
-- Seed: listings (8 benchmark stocks)
-- ---------------------------------------------------------------------------


-- ---------------------------------------------------------------------------
-- Data: adj_eod (65936 rows, 500 per INSERT)
-- ---------------------------------------------------------------------------






































































































































\echo '>>> Done.'
SELECT
    l.exchange_code,
    l.code,
    COUNT(e.ts) AS eod_rows
FROM listing l
JOIN adj_eod e ON l.listing_id = e.listing_id
GROUP BY l.exchange_code, l.code
ORDER BY l.exchange_code, l.code;
